import com.geoattend.app.EcdsaSignature;import java.security.*;import java.security.spec.ECGenParameterSpec;import java.util.Base64;
public final class EcdsaSignatureTest {
 public static void main(String[] args) throws Exception {KeyPairGenerator g=KeyPairGenerator.getInstance("EC");g.initialize(new ECGenParameterSpec("secp256r1"));KeyPair pair=g.generateKeyPair();byte[] message="Geo Attend phone verification".getBytes(java.nio.charset.StandardCharsets.UTF_8);for(int i=0;i<100;i++){Signature sign=Signature.getInstance("SHA256withECDSA");sign.initSign(pair.getPrivate());sign.update(message);byte[] raw=EcdsaSignature.toP1363(sign.sign());Signature verify=Signature.getInstance("SHA256withECDSAinP1363Format");verify.initVerify(pair.getPublic());verify.update(message);if(raw.length!=64||!verify.verify(raw))throw new AssertionError("Signature conversion failed");if(i==0)System.out.println(Base64.getEncoder().encodeToString(pair.getPublic().getEncoded())+" "+Base64.getEncoder().encodeToString(message)+" "+Base64.getEncoder().encodeToString(raw));}try{EcdsaSignature.toP1363(new byte[]{48,1,2});throw new AssertionError("Malformed signature accepted");}catch(IllegalArgumentException expected){}System.out.println("PASS: 100 generated signatures and malformed signature rejection.");}
}
